    """
    # Check if the number is negative
    if number < 0:
        return None
    # Check if the number is 0
    if number == 0:
        return 0
    # Check if the number is 1
    if number == 1:
        return 1
    # Check if the number is not a prime number
    if number % 2 == 0:
