def re_order(arr):
    for i in range(len(arr)):
        if arr[i] == 0:
            arr.remove(0)
            arr.append(0)
    return arr

def permutation_coefficient(n, k):
    """
    :param n: number of elements in the permutation
    :param k: number of elements in the permutation
    :return: the permutation coefficient
    """
    if n == 0 or k == 0:
        return 1
    if n == 1:
        return k
    return permutation_coefficient(n - 1, k) + permutation_coefficient(n - 1, k - 1)

